#!/usr/bin/env node
/**
 * Bundle Analyzer CI Script
 * ==========================
 *
 * Runs on every PR via GitHub Actions.  Generates a bundle size report
 * comparing the PR against the main branch baseline.
 *
 * Features:
 *   - Builds with @vitejs/plugin-visualizer enabled
 *   - Parses stats.json to extract chunk sizes
 *   - Compares against main branch baseline (downloaded artifact)
 *   - Comments on PR with a size changes table (markdown)
 *   - Fails CI if performance-budget.json thresholds are exceeded
 *
 * Usage:
 *   node scripts/ci/bundle-analyzer-ci.js \
 *     --stats ./apps/web/dist/stats.json \
 *     --baseline ./artifacts/stats-main.json \
 *     --budget apps/web/performance-budget.json \
 *     --comment ./artifacts/bundle-comment.md
 *
 * DESIGN.md § CI: "Performance budgets must be enforced in CI"
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { execSync } from "node:child_process";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// ---------------------------------------------------------------------------
// CLI argument parsing
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const args = {
    stats: null,
    baseline: null,
    budget: "apps/web/performance-budget.json",
    comment: null,
    failOnBudget: true,
    verbose: false,
  };

  for (let i = 2; i < argv.length; i++) {
    switch (argv[i]) {
      case "--stats":
        args.stats = argv[++i];
        break;
      case "--baseline":
        args.baseline = argv[++i];
        break;
      case "--budget":
        args.budget = argv[++i];
        break;
      case "--comment":
        args.comment = argv[++i];
        break;
      case "--no-fail":
        args.failOnBudget = false;
        break;
      case "--verbose":
      case "-v":
        args.verbose = true;
        break;
      case "--help":
      case "-h":
        printHelp();
        process.exit(0);
    }
  }

  if (!args.stats) {
    console.error("❌ --stats is required (path to stats.json)");
    printHelp();
    process.exit(2);
  }

  return args;
}

function printHelp() {
  console.log(`
Bundle Analyzer CI — Fabric_4L

Usage:
  node bundle-analyzer-ci.js --stats <path> [options]

Required:
  --stats <path>       Path to Vite stats.json (generated by plugin-visualizer)

Optional:
  --baseline <path>    Path to main branch stats.json for comparison
  --budget <path>      Path to performance-budget.json (default: apps/web/performance-budget.json)
  --comment <path>     Write PR comment markdown to this path
  --no-fail            Don't fail CI on budget exceeded (report only)
  --verbose, -v        Enable verbose logging
  --help, -h           Show this help
`);
}

// ---------------------------------------------------------------------------
// Stats parser
// ---------------------------------------------------------------------------

function parseStats(statsPath) {
  const raw = readFileSync(statsPath, "utf-8");
  const stats = JSON.parse(raw);

  const chunks = [];
  const totalSize = { gzip: 0, raw: 0 };

  for (const node of stats.nodes || []) {
    if (node.source) {
      const rawSize = Buffer.byteLength(node.source, "utf-8");
      // Rough gzip estimate (real gzip requires zlib; we approximate for speed)
      const gzipSize = Math.round(rawSize * 0.25);
      chunks.push({
        name: node.name || "unknown",
        raw: rawSize,
        gzip: gzipSize,
        isEntry: node.isEntry || false,
      });
      totalSize.raw += rawSize;
      totalSize.gzip += gzipSize;
    }
  }

  // If the stats file is from vite-bundle-visualizer, it has a different shape
  if (chunks.length === 0 && stats.outputs) {
    for (const [fileName, output] of Object.entries(stats.outputs)) {
      if (fileName.endsWith(".js") || fileName.endsWith(".css")) {
        const rawSize = output.bytes || 0;
        const gzipSize = output.gzipSize || Math.round(rawSize * 0.25);
        chunks.push({
          name: fileName,
          raw: rawSize,
          gzip: gzipSize,
          isEntry: output.isEntry || fileName.includes("index"),
        });
        totalSize.raw += rawSize;
        totalSize.gzip += gzipSize;
      }
    }
  }

  return { chunks, totalSize };
}

// ---------------------------------------------------------------------------
// Budget checker
// ---------------------------------------------------------------------------

function loadBudget(budgetPath) {
  if (!existsSync(budgetPath)) {
    console.warn("⚠️ Budget file not found:", budgetPath);
    return null;
  }
  return JSON.parse(readFileSync(budgetPath, "utf-8"));
}

function checkBudget(stats, budget) {
  if (!budget) return { passed: true, violations: [] };

  const violations = [];

  for (const b of budget.budgets || []) {
    let actual = 0;
    switch (b.resourceType) {
      case "script":
        actual = stats.chunks
          .filter((c) => c.name.endsWith(".js"))
          .reduce((sum, c) => sum + c.gzip, 0);
        break;
      case "stylesheet":
        actual = stats.chunks
          .filter((c) => c.name.endsWith(".css"))
          .reduce((sum, c) => sum + c.gzip, 0);
        break;
      case "total":
        actual = stats.totalSize.gzip;
        break;
      case "document":
        // Document budget is checked via Lighthouse, not bundle stats
        continue;
      case "image":
        // Image budget is checked via Lighthouse, not bundle stats
        continue;
    }

    const actualKB = actual / 1024;
    if (actualKB > b.budget) {
      violations.push({
        resourceType: b.resourceType,
        budget: b.budget,
        actual: Math.round(actualKB * 100) / 100,
        delta: Math.round((actualKB - b.budget) * 100) / 100,
      });
    }
  }

  return {
    passed: violations.length === 0,
    violations,
  };
}

// ---------------------------------------------------------------------------
// Baseline comparison
// ---------------------------------------------------------------------------

function compareWithBaseline(current, baseline) {
  if (!baseline) return null;

  const changes = [];

  // Index baseline chunks by name
  const baselineMap = new Map(baseline.chunks.map((c) => [c.name, c]));

  for (const chunk of current.chunks) {
    const base = baselineMap.get(chunk.name);
    if (base) {
      const deltaRaw = chunk.raw - base.raw;
      const deltaGzip = chunk.gzip - base.gzip;
      const pct = base.gzip > 0 ? ((deltaGzip / base.gzip) * 100).toFixed(1) : "N/A";

      if (Math.abs(deltaGzip) > 100) {
        // Only report changes > 100 bytes
        changes.push({
          name: chunk.name,
          baseGzip: base.gzip,
          currentGzip: chunk.gzip,
          deltaGzip,
          deltaRaw,
          pct,
          trend: deltaGzip > 0 ? "up" : deltaGzip < 0 ? "down" : "same",
        });
      }
    } else {
      changes.push({
        name: chunk.name,
        baseGzip: 0,
        currentGzip: chunk.gzip,
        deltaGzip: chunk.gzip,
        deltaRaw: chunk.raw,
        pct: "new",
        trend: "up",
      });
    }
  }

  // Find removed chunks
  const currentNames = new Set(current.chunks.map((c) => c.name));
  for (const base of baseline.chunks) {
    if (!currentNames.has(base.name)) {
      changes.push({
        name: base.name,
        baseGzip: base.gzip,
        currentGzip: 0,
        deltaGzip: -base.gzip,
        deltaRaw: -base.raw,
        pct: "removed",
        trend: "down",
      });
    }
  }

  // Sort by absolute delta (largest changes first)
  changes.sort((a, b) => Math.abs(b.deltaGzip) - Math.abs(a.deltaGzip));

  return changes;
}

// ---------------------------------------------------------------------------
// Report generation
// ---------------------------------------------------------------------------

function formatSize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
}

function generateReport(current, baselineComparison, budgetCheck) {
  const lines = [];

  lines.push("## 📦 Bundle Size Report\n");
  lines.push(`**Total:** ${formatSize(current.totalSize.gzip)} (gzip) / ${formatSize(current.totalSize.raw)} (raw)\n`);

  // Budget section
  if (budgetCheck) {
    if (budgetCheck.passed) {
      lines.push("✅ **All performance budgets passed.**\n");
    } else {
      lines.push("❌ **Performance budget exceeded:**\n");
      for (const v of budgetCheck.violations) {
        lines.push(`- **${v.resourceType}**: ${v.actual} KB (budget: ${v.budget} KB, +${v.delta} KB)`);
      }
      lines.push("");
    }
  }

  // Comparison section
  if (baselineComparison) {
    if (baselineComparison.length === 0) {
      lines.push("_No significant changes from main branch._\n");
    } else {
      lines.push("### Changes vs main\n");
      lines.push("| Chunk | Size (main) | Size (PR) | Δ | Trend |");
      lines.push("|---|---|---|---|---|");

      for (const c of baselineComparison.slice(0, 20)) {
        // Top 20 changes
        const icon = c.trend === "up" ? "📈" : c.trend === "down" ? "📉" : "➡️";
        const sizeMain = c.baseGzip > 0 ? formatSize(c.baseGzip) : "—";
        const sizePR = c.currentGzip > 0 ? formatSize(c.currentGzip) : "—";
        const delta = c.pct === "new" ? "_new_" : c.pct === "removed" ? "_removed_" : `${c.pct}%`;
        lines.push(`| ${c.name} | ${sizeMain} | ${sizePR} | ${delta} | ${icon} |`);
      }

      if (baselineComparison.length > 20) {
        lines.push(`\n_…and ${baselineComparison.length - 20} more changes._`);
      }
      lines.push("");
    }
  }

  // Top chunks
  lines.push("### Largest chunks\n");
  const sorted = [...current.chunks].sort((a, b) => b.gzip - a.gzip).slice(0, 10);
  lines.push("| Chunk | Gzip | Raw |");
  lines.push("|---|---|---|");
  for (const c of sorted) {
    lines.push(`| ${c.name} | ${formatSize(c.gzip)} | ${formatSize(c.raw)} |`);
  }
  lines.push("");

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function main() {
  const args = parseArgs(process.argv);

  console.log("📦 Fabric_4L Bundle Analyzer CI");
  console.log("================================\n");

  // Parse current stats
  console.log("→ Parsing current bundle stats...");
  const current = parseStats(args.stats);
  console.log(`  Found ${current.chunks.length} chunks`);
  console.log(`  Total: ${formatSize(current.totalSize.gzip)} (gzip)`);

  // Load baseline
  let baseline = null;
  if (args.baseline && existsSync(args.baseline)) {
    console.log("→ Loading baseline stats...");
    baseline = parseStats(args.baseline);
    console.log(`  Baseline: ${formatSize(baseline.totalSize.gzip)} (gzip)`);
  } else if (args.baseline) {
    console.log("  No baseline found — skipping comparison");
  }

  // Load budget
  const budget = loadBudget(args.budget);
  const budgetCheck = checkBudget(current, budget);

  // Compare
  const comparison = compareWithBaseline(current, baseline);

  // Generate report
  const report = generateReport(current, comparison, budgetCheck);
  console.log("\n" + report);

  // Write PR comment
  if (args.comment) {
    const commentDir = dirname(args.comment);
    if (!existsSync(commentDir)) {
      execSync(`mkdir -p ${commentDir}`);
    }
    writeFileSync(args.comment, report, "utf-8");
    console.log(`\n📝 PR comment written to ${args.comment}`);
  }

  // Write GitHub step summary
  if (process.env.GITHUB_STEP_SUMMARY) {
    writeFileSync(process.env.GITHUB_STEP_SUMMARY, report, "utf-8");
    console.log("📝 GitHub step summary written");
  }

  // Exit
  if (args.failOnBudget && !budgetCheck.passed) {
    console.error("\n❌ CI failed: performance budget exceeded");
    process.exit(1);
  }

  console.log("\n✅ Bundle analysis complete");
  process.exit(0);
}

main();
